200	// ====== 可用行动列表 ======
201	function getAvailableActions(state) {
202	  const actions = [];
203	
204	  // 提升为函数级变量（用 let，块内可重新指向用 const）
205	  const locKey = state.trade.currentLocation;
206	
207	  if (state.player.phase === "street") {
208	    // --- 街头阶段行动 ---
209	
210	    // 1. 工作
211	    const jobIds = getJobsAtLocation(locKey);
212	    for (const jobId of jobIds) {
213	      const job = getJobById(jobId);
214	      if (!job) continue;
215	      const reqFail = checkJobRequirements(job, state);
216	      const payEstimate = reqFail ? null : estimateJobPay(job, state);
217	
218	      actions.push({
219	        id: "job_" + jobId,
220	        name: job.name,
221	        desc: job.desc,
222	        icon: job.icon,
223	        payEstimate: payEstimate
224	          ? `${payEstimate - (job.startupCost || 0)}~${payEstimate + Math.floor(payEstimate * 0.3)}`
225	          : null,
226	        costEstimate: job.startupCost || null,
227	        reqFail,
228	        disabled:
229	          !!reqFail ||
230	          (job.startupCost && state.resources.cash < job.startupCost
231	            ? `启动资金不足(需¥${job.startupCost})`
232	            : null) ||
233	          null,
234	        handler: () => {
235	          const finalReq = checkJobRequirements(job, state);
236	          if (finalReq) {
237	            StateManager.addMessage(`⚠️ ${finalReq}`, "warning");
238	            return;
239	          }
240	          if (job.startupCost && state.resources.cash < job.startupCost) {
241	            StateManager.addMessage(
242	              `⚠️ 启动资金不足，需要 ¥${job.startupCost}`,
243	              "warning",
244	            );
245	            return;
246	          }
247	          doStreetJob(job);
248	        },
249	      });
250	    }
251	
252	    // 如果没有可用工作
253	    if (jobIds.length === 0) {
254	      actions.push({
255	        id: "no_jobs",
256	        name: "当前地点没有工作机会",
257	        desc: "尝试旅行到其他地点寻找工作。",
258	        icon: "🚫",
259	        disabled: true,
260	      });
261	    }
262	
263	    // 批发市场 — 批发进货
264	    if (locKey === "wholesaleMarket") {
265	      actions.push({
266	        id: "wholesale_header",
267	        name: "📦 批发进货（转到交易Tab）",
268	        desc: "在批发市场以折扣价批量购入商品，转手到商业区卖出赚差价！",
269	        icon: "📦",
270	        handler: () => {
271	          switchTab("trade");
272	        },
273	      });
274	    }
275	
276	    // 零售买卖 — 在任何有价格数据的地点都可以买卖
277	    if (
278	      state.trade.goodsPrices[locKey] &&
279	      Object.keys(state.trade.goodsPrices[locKey]).length > 0
280	    ) {
281	      actions.push({
282	        id: "trade_header",
283	        name: "🛒 买卖商品（转到交易Tab）",
284	        desc: "查看当前市场价格，低买高卖赚取差价。",
285	        icon: "🛒",
286	        handler: () => {
287	          switchTab("trade");
288	        },
289	      });
290	    }
291	
292	    // === 住所系统 ===
293	    if (locKey === "slum") {
294	      const currentTier = state.housing?.tier || 0;
295	      const HOUSING_TIERS = [
296	        {
297	          tier: 0,
298	          name: "露宿街头",
299	          cost: 0,
300	          rent: 0,
301	          capacity: 20,
302	          fatigueRecovery: 15,
303	          desc: "天为被，地为床。碰上刮风下雨就惨了。",
304	          icon: "🌃",
305	        },
306	        {
307	          tier: 1,
308	          name: "合租床位",
309	          cost: 300,
310	          rent: 12,
311	          capacity: 50,
312	          fatigueRecovery: 25,
313	          hygieneBonus: 5,
314	          desc: "城中村合租屋的一个床位，好歹有个遮风挡雨的地方。",
315	          icon: "🛏️",
316	        },
317	        {
318	          tier: 2,
319	          name: "单间",
320	          cost: 800,
321	          rent: 25,
322	          capacity: 100,
323	          fatigueRecovery: 35,
324	          hygieneBonus: 10,
325	          happinessBonus: 5,
326	          desc: "独立小单间，有床有柜子，私密多了。",
327	          icon: "🚪",
328	        },
329	        {
330	          tier: 3,
331	          name: "一居室",
332	          cost: 2000,
333	          rent: 50,
334	          capacity: 200,
335	          fatigueRecovery: 50,
336	          hygieneBonus: 15,
337	          happinessBonus: 10,
338	          desc: "正经的一室一厅，独立卫浴，生活质量质的飞跃。",
339	          icon: "🏠",
340	        },
341	      ];
342	
343	      // 显示当前住所
344	      const curHouse = HOUSING_TIERS[currentTier];
345	      actions.push({
346	        id: "housing_current",
347	        name: `${curHouse.icon} 当前住所：${curHouse.name}`,
348	        desc: `容量+${curHouse.capacity} | 睡眠恢复疲劳-${curHouse.fatigueRecovery} | ${curHouse.desc}${curHouse.rent > 0 ? ` | 日租¥${curHouse.rent}/天` : ""}`,
349	        icon: curHouse.icon,
350	        disabled: true,
351	      });
352	
353	      // 可升级的住所
354	      for (let t = currentTier + 1; t < HOUSING_TIERS.length; t++) {
355	        const house = HOUSING_TIERS[t];
356	        const canAfford = state.resources.cash >= house.cost;
357	        actions.push({
358	          id: "housing_upgrade_" + t,
359	          name: `⬆️ 升级到${house.name}`,
360	          desc: `${house.desc} 一次性付¥${house.cost} + 日租¥${house.rent}/天`,
361	          icon: house.icon,
362	          costEstimate: house.cost,
363	          disabled: !canAfford,
364	          reqFail: !canAfford ? `需 ¥${house.cost}` : null,
365	          handler: () => {
366	            state.resources.cash -= house.cost;
367	            state.housing.tier = t;
368	            state.housing.rentedDay = state.player.day;
369	            state.inventory.capacity =
370	              house.capacity + (state.housing.storageCapacity || 0);
371	            StateManager.addMessage(
372	              `🏠 搬进了${house.name}！容量提升至${state.inventory.capacity}。`,
373	              "success",
374	            );
375	          },
376	        });
377	      }
378	    }
379	
380	    // === 仓库租赁（批发市场）===
381	    if (locKey === "wholesaleMarket") {
382	      const hasStorage = state.housing?.storageRented;
383	      const STORAGE_OPTIONS = [
384	        {
385	          id: "small",
386	          name: "小仓库",
387	          cost: 500,
388	          rent: 20,
389	          capacity: 150,
390	          icon: "📦",
391	        },
392	        {
393	          id: "big",
394	          name: "大仓库",
395	          cost: 1500,
396	          rent: 50,
397	          capacity: 500,
398	          icon: "🏗️",
399	        },
400	      ];
401	
402	      if (hasStorage) {
403	        actions.push({
404	          id: "storage_current",
405	          name: `📦 已租仓库 (额外+${state.housing.storageCapacity || 0}容量)`,
406	          desc: `日租¥${STORAGE_OPTIONS.find((s) => s.capacity === state.housing.storageCapacity)?.rent || "?"}/天`,
407	          icon: "📦",
408	          disabled: true,
409	        });
410	      } else {
411	        for (const opt of STORAGE_OPTIONS) {
412	          const canAfford = state.resources.cash >= opt.cost;
413	          actions.push({
414	            id: "storage_rent_" + opt.id,
415	            name: `📦 租用${opt.name}`,
416	            desc: `额外+${opt.capacity}商品存储容量。一次性¥${opt.cost} + 日租¥${opt.rent}/天`,
417	            icon: opt.icon,
418	            costEstimate: opt.cost,
419	            disabled: !canAfford,
420	            reqFail: !canAfford ? `需 ¥${opt.cost}` : null,
421	            handler: () => {
422	              state.resources.cash -= opt.cost;
423	              state.housing.storageRented = true;
424	              state.housing.storageCapacity = opt.capacity;
425	              const baseCap = [20, 50, 100, 200][state.housing.tier || 0];
426	              state.inventory.capacity = baseCap + opt.capacity;
427	              StateManager.addMessage(
428	                `📦 租下了${opt.name}！总容量提升至${state.inventory.capacity}。`,
429	                "success",
430	              );
431	            },
432	          });
433	        }
434	      }
435	    }
436	
437	    // === 背包升级（商业区）===
438	    if (locKey === "commercialDist") {
439	      const BACKPACKS = [
440	        {
441	          id: "backpack_basic",
442	          name: "帆布背包",
443	          cost: 50,
444	          capacity: 5,
445	          icon: "🎒",
446	        },
447	        {
448	          id: "backpack_large",
449	          name: "大号旅行包",
450	          cost: 150,
451	          capacity: 15,
452	          icon: "🎒",
453	        },
454	        {
455	          id: "backpack_pro",
456	          name: "专业登山包",
457	          cost: 400,
458	          capacity: 30,
459	          icon: "🎒",
460	        },
461	      ];
462	      // 只显示未购买的
463	      const ownedPacks = state.inventory.items.filter((i) =>
464	        i.id.startsWith("backpack_"),
465	      );
466	      for (const pack of BACKPACKS) {
467	        if (ownedPacks.find((p) => p.id === pack.id)) continue;
468	        const canAfford = state.resources.cash >= pack.cost;
469	        actions.push({
470	          id: "buy_" + pack.id,
471	          name: `🛍️ 购买${pack.name}`,
472	          desc: `随身容量+${pack.capacity}。一次性购买，永久拥有。`,
473	          icon: pack.icon,
474	          costEstimate: pack.cost,
475	          disabled: !canAfford,
476	          handler: () => {
477	            state.resources.cash -= pack.cost;
478	            state.inventory.items.push({ id: pack.id, qty: 1 });
479	            state.inventory.capacity += pack.capacity;
480	            StateManager.addMessage(
481	              `🎒 购买了${pack.name}，随身容量+${pack.capacity}！`,
482	              "success",
483	            );
484	          },
485	        });
486	      }
487	    }
488	
489	    // 2. 旅行
490	    const reachable = getReachableLocations(locKey);
491	    for (const destKey of reachable) {
492	      const dest = getLocation(destKey);
493	      if (!dest) continue;
494	      actions.push({
495	        id: "travel_" + destKey,
496	        name: `前往 ${dest.name}`,
497	        desc: dest.desc,
498	        icon: "🚶",
499	        handler: () => {
500	          StateManager.update("trade.currentLocation", destKey);
501	          StateManager.addMessage(`🚶 你来到了${dest.name}。`, "info");
502	        },
503	      });
504	    }
505	
506	    // 3. 通用行动
507	    actions.push({
508	      id: "rest",
509	      name: "休息一会",
510	      desc: "找个地方坐坐，恢复一些疲劳。",
511	      icon: "😴",
512	      handler: () => {
513	        const state = StateManager.getState();
514	        const recovery = 25 + Math.floor(Math.random() * 15);
515	        state.needs.fatigue = Math.max(0, state.needs.fatigue - recovery);
516	        state.needs.happiness = Math.min(100, state.needs.happiness + 5);
517	        StateManager.addMessage(`😴 你休息了一会，疲劳-${recovery}。`, "info");
518	      },
519	    });
520	
521	    actions.push({
522	      id: "eat",
523	      name: "吃顿饭",
524	      desc: "花10元在路边摊吃个快餐，填饱肚子。",
525	      icon: "🍚",
526	      costEstimate: 10,
527	      disabled: state.resources.cash < 10 ? true : false,
528	      handler: () => {
529	        const st = StateManager.getState();
530	        if (st.resources.cash < 10) {
531	          StateManager.addMessage("⚠️ 钱不够吃饭了！", "danger");
532	          return;
533	        }
534	        st.resources.cash -= 10;
535	        st.needs.hunger = Math.min(100, st.needs.hunger + 35);
536	        st.needs.happiness = Math.min(100, st.needs.happiness + 8);
537	        StateManager.addMessage(
538	          "🍚 你花10元吃了顿饭，肚子饱了心情好了。",
539	          "success",
540	        );
541	      },
542	    });
543	
544	    actions.push({
545	      id: "shower",
546	      name: "洗澡",
547	      desc: "花5元去公共澡堂洗个澡。",
