990	function addSkillXp(skillKey, amount) {
991	  if (!amount || amount <= 0) return;
992	  const state = StateManager.getState();
993	  const skill = state.skills[skillKey];
994	  if (!skill) return;
995	  skill.xp += amount;
996	  const xpNeeded = (skill.level + 1) * 100;
997	  if (skill.xp >= xpNeeded && skill.level < 100) {
998	    skill.level++;
999	    skill.xp -= xpNeeded;
1000	    StateManager.addMessage(
1001	      `⭐ ${getSkillName(skillKey)}升级到 Lv.${skill.level}！`,
1002	      "success",
1003	    );
1004	  }
1005	}
