168	// ====== 状态管理器 ======
169	class GameStateManager {
170	  constructor() {
171	    this._state = null;
172	    this._dirtyFlags = new Set();
173	    this._listeners = [];
174	  }
175	
176	  /** 初始化新游戏 */
177	  newGame() {
178	    this._state = createDefaultState();
179	    this._markAllDirty();
180	    this._notify();
181	    return this._state;
182	  }
183	
184	  /** 获取当前完整状态（只读引用，请勿直接修改嵌套对象） */
185	  getState() {
186	    if (!this._state) {
187	      throw new Error(
188	        "GameState not initialized. Call newGame() or loadGame() first.",
189	      );
190	    }
191	    return this._state;
192	  }
193	
194	  /** 获取状态某个路径的值 */
195	  get(path) {
196	    const parts = path.split(".");
197	    let val = this.getState();
198	    for (const p of parts) {
199	      if (val == null) return undefined;
200	      val = val[p];
201	    }
202	    return val;
203	  }
204	
205	  /**
206	   * 更新状态某个路径的值
207	   * 用法: update('player.age', 25) 或 update('player', { age: 25, ... })
208	   */
209	  update(path, value) {
210	    const parts = path.split(".");
211	    const state = this.getState();
212	
213	    // 导航到父对象
214	    let parent = state;
215	    for (let i = 0; i < parts.length - 1; i++) {
216	      parent = parent[parts[i]];
217	    }
218	
219	    const key = parts[parts.length - 1];
220	    parent[key] = value;
221	
222	    // 标记脏路径
223	    this._dirtyFlags.add(path);
224	    this._notify();
225	  }
226	
227	  /** 批量更新（用于一次性修改多个字段） */
228	  batchUpdate(updates) {
229	    for (const [path, value] of Object.entries(updates)) {
230	      const parts = path.split(".");
231	      const state = this.getState();
232	      let parent = state;
233	      for (let i = 0; i < parts.length - 1; i++) {
234	        parent = parent[parts[i]];
235	      }
236	      parent[parts[parts.length - 1]] = value;
237	      this._dirtyFlags.add(path);
238	    }
239	    this._notify();
240	  }
241	
242	  /** 添加消息到日志 */
243	  addMessage(text, type = "info") {
244	    const state = this.getState();
245	    state.messageLog.push({
246	      day: state.player.day,
247	      text,
248	      type, // 'info'|'success'|'danger'|'event'|'warning'
249	    });
250	    // 限制日志长度
251	    if (state.messageLog.length > 500) {
252	      state.messageLog = state.messageLog.slice(-300);
253	    }
254	    this._dirtyFlags.add("messageLog");
255	    this._notify();
256	  }
257	
258	  /** 导入存档 */
259	  importState(savedState) {
260	    this._state = savedState;
261	    this._state.lastPlayedAt = Date.now();
262	    this._markAllDirty();
263	    this._notify();
264	  }
265	
266	  /** 检查路径是否脏（自上次 cleanDirty 后） */
267	  isDirty(path) {
268	    return this._dirtyFlags.has(path);
269	  }
270	
271	  /** 清除所有脏标记（渲染后调用） */
272	  cleanAllDirty() {
273	    this._dirtyFlags.clear();
274	  }
275	
276	  /** 订阅状态变更 */
277	  onChange(callback) {
278	    this._listeners.push(callback);
279	  }
280	
281	  // ====== 内部方法 ======
282	  _markAllDirty() {
283	    this._dirtyFlags.add("*");
284	  }
285	
286	  _notify() {
287	    for (const cb of this._listeners) {
288	      try {
289	        cb(this._state);
290	      } catch (e) {
291	        /* 静默 */
292	      }
293	    }
294	  }
295	}
296	
