/**
 * GameState — 唯一状态源 (Single Source of Truth)
 *
 * 所有游戏数据集中在此对象中。每个模块通过 getState()/updateState() 读写。
 * 使用 Proxy 实现变更追踪（dirty flag），驱动按需渲染。
 */

// ====== 默认初始状态 ======
function createDefaultState() {
  const now = Date.now();
  return {
    // --- 元数据 ---
    version: "1.0.0",
    createdAt: now,
    lastPlayedAt: now,
    playTime: 0,

    // --- 玩家身份 ---
    player: {
      name: "无名",
      gender: "male",
      age: 20,
      birthday: { month: 6, day: 15 },

      // 街头 4 维属性 (0-100)
      physique: 22, // 体质
      intelligence: 20, // 智力
      agility: 24, // 敏捷
      mental: 26, // 心智

      // 职场 7 维属性 (进入职场后初始化)
      corporate: {
        hair: 100,
        dignity: 60,
        upwardMgmt: 20,
        kpi: 20,
        ability: 30,
        risk: 0,
        popularity: 30,
      },

      // 阶段与时间
      phase: "street", // 'street' | 'corporate'
      day: 1,
      corpYear: 0, // 入职年数
      corpQuarter: 1, // 1-4
      timeSlot: "morning", // 'morning' | 'afternoon' | 'evening'
    },

    // --- 经济 ---
    resources: {
      cash: 2000, // 现金（元）
      bankBalance: 0, // 银行存款
      debt: 5500, // 当前欠款
      loanPrincipal: 5500, // 原始借款额
      loanDay: 0, // 借款日
      dailyInterest: 0.003, // 日息 0.3%
      totalEarned: 0, // 终身总收入
    },

    // --- 基本需求 (0-100) ---
    needs: {
      hunger: 70,
      fatigue: 15,
      hygiene: 75,
      happiness: 55,
    },

    // --- 派生状态 ---
    status: {
      health: 100,
      fame: 0,
      emotionalState: "stable", // stable|happy|sad|angry|stressed|depressed
      sick: false,
      injured: false,
    },

    // --- 技能 (level: 0-100, xp: 0-1000) ---
    skills: {
      cooking: { level: 0, xp: 0 },
      repair: { level: 0, xp: 0 },
      coding: { level: 0, xp: 0 },
      english: { level: 0, xp: 0 },
      driving: { level: 0, xp: 0 },
      sales: { level: 0, xp: 0 },
      management: { level: 0, xp: 0 },
      accounting: { level: 0, xp: 0 },
      electrician: { level: 0, xp: 0 },
      welding: { level: 0, xp: 0 },
    },
    certificates: [],
    education: 0,

    // --- 物品栏 ---
    inventory: {
      items: [], // [{ id, qty, avgBuyPrice }]
      capacity: 20, // 基础容量
      equipment: {
        head: null,
        body: null,
        feet: null,
        hand: null,
        accessory: null,
      },
    },

    // --- 住所 ---
    housing: {
      tier: 0, // 0=露宿, 1=合租床位, 2=单间, 3=一居室
      rentedDay: 0, // 租房日
      storageRented: false, // 是否租了仓库
      storageCapacity: 0, // 仓库额外容量
    },

