392	}
393	
394	/* --- Action Cards Grid --- */
395	.action-cards {
396	  display: grid;
397	  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
398	  gap: 10px;
399	}
400	
401	.action-card {
402	  background: var(--bg-card);
403	  border: 1px solid var(--border);
404	  border-radius: var(--radius-md);
405	  padding: 14px;
406	  cursor: pointer;
407	  transition: all var(--transition);
408	}
409	
410	.action-card:hover {
411	  background: var(--bg-card-hover);
412	  border-color: var(--accent);
413	  transform: translateY(-1px);
414	  box-shadow: 0 4px 12px rgba(0, 180, 216, 0.1);
415	}
416	
417	.action-card.disabled {
418	  opacity: 0.4;
419	  cursor: not-allowed;
420	}
421	
422	.action-card.disabled:hover {
423	  border-color: var(--border);
424	  transform: none;
425	  box-shadow: none;
426	}
427	
428	.action-card .card-icon {
429	  font-size: 24px;
430	  margin-bottom: 6px;
431	}
432	
433	.action-card .card-title {
434	  font-size: 14px;
435	  font-weight: 600;
436	  color: var(--text-primary);
437	  margin-bottom: 4px;
438	}
439	
440	.action-card .card-desc {
441	  font-size: 11px;
442	  color: var(--text-muted);
443	  margin-bottom: 8px;
444	  line-height: 1.4;
445	}
446	
447	.action-card .card-meta {
448	  display: flex;
449	  justify-content: space-between;
450	  align-items: center;
451	  font-size: 11px;
452	}
453	
454	.card-meta .pay-estimate {
455	  color: var(--success);
456	  font-weight: 600;
457	}
458	
459	.card-meta .cost-estimate {
460	  color: var(--danger);
461	  font-weight: 600;
462	}
463	
464	.card-meta .slot-tag {
465	  padding: 1px 6px;
466	  border-radius: var(--radius-sm);
467	  font-size: 10px;
468	  background: rgba(0, 180, 216, 0.1);
469	  color: var(--accent);
470	}
471	
472	.card-meta .req-fail {
473	  color: var(--danger);
474	  font-size: 10px;
475	}
476	
477	/* --- Message Log --- */
478	#message-log {
479	  background: var(--bg-card);
480	  border: 1px solid var(--border);
481	  border-radius: var(--radius-md);
482	  padding: 12px;
483	  max-height: 250px;
484	  overflow-y: auto;
485	  flex-shrink: 0;
486	}
487	
488	#message-log h3 {
489	  font-size: 11px;
490	  text-transform: uppercase;
491	  letter-spacing: 1px;
492	  color: var(--text-muted);
493	  margin-bottom: 8px;
494	  font-weight: 600;
495	}
496	
497	.log-entry {
498	  padding: 3px 0;
499	  font-size: 12px;
500	  border-bottom: 1px solid rgba(255, 255, 255, 0.03);
501	  animation: fadeIn 0.3s ease;
502	}
503	
504	.log-entry .log-day {
505	  color: var(--text-muted);
506	  font-size: 10px;
507	  margin-right: 8px;
508	  font-family: var(--font-mono);
509	}
510	
511	.log-entry.info {
512	  color: var(--text-secondary);
513	}
514	.log-entry.success {
515	  color: var(--success);
516	}
517	.log-entry.danger {
518	  color: var(--danger);
519	}
520	.log-entry.warning {
521	  color: var(--warning);
522	}
523	.log-entry.event {
524	  color: var(--accent);
525	  font-weight: 600;
526	}
527	
528	/* --- Inventory Grid --- */
529	.inventory-grid {
530	  display: grid;
531	  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
532	  gap: 8px;
533	}
534	
535	.inventory-item {
536	  background: var(--bg-card);
537	  border: 1px solid var(--border);
538	  border-radius: var(--radius-sm);
539	  padding: 10px;
540	  font-size: 12px;
541	}
542	
543	.inventory-item .item-name {
544	  font-weight: 600;
545	  color: var(--text-primary);
546	}
547	
548	.inventory-item .item-qty {
549	  color: var(--text-muted);
550	  font-size: 10px;
551	}
552	
553	.inventory-item .item-effects {
554	  color: var(--success);
555	  font-size: 10px;
556	}
557	
558	/* ====== Buttons ====== */
559	.btn {
560	  display: inline-flex;
561	  align-items: center;
562	  justify-content: center;
563	  gap: 6px;
564	  padding: 8px 16px;
565	  font-size: 13px;
566	  font-family: var(--font-sans);
567	  font-weight: 500;
568	  border: 1px solid var(--border);
569	  border-radius: var(--radius-sm);
570	  cursor: pointer;
571	  transition: all var(--transition);
572	  background: var(--bg-card);
573	  color: var(--text-primary);
574	  white-space: nowrap;
575	}
576	
577	.btn:hover {
578	  background: var(--bg-card-hover);
579	  border-color: var(--border-light);
580	}
581	
582	.btn:active {
583	  transform: scale(0.97);
584	}
585	
586	.btn-primary {
587	  background: var(--accent);
588	  border-color: var(--accent);
589	  color: #fff;
590	}
591	
592	.btn-primary:hover {
593	  background: var(--accent-hover);
594	}
595	
596	.btn-success {
597	  background: var(--success);
598	  border-color: var(--success);
599	  color: #fff;
600	}
601	
602	.btn-danger {
603	  background: var(--danger);
604	  border-color: var(--danger);
605	  color: #fff;
606	}
607	
608	.btn-sm {
609	  padding: 4px 10px;
610	  font-size: 11px;
611	}
612	
613	.btn-lg {
614	  padding: 12px 24px;
615	  font-size: 15px;
616	  border-radius: var(--radius-md);
617	}
618	
619	/* ====== Modal ====== */
620	.modal-overlay {
621	  position: fixed;
622	  top: 0;
623	  left: 0;
624	  right: 0;
625	  bottom: 0;
626	  background: rgba(0, 0, 0, 0.7);
627	  display: flex;
628	  align-items: center;
629	  justify-content: center;
630	  z-index: 1000;
631	  animation: fadeIn 0.2s ease;
632	}
633	
634	.modal-box {
635	  background: var(--bg-secondary);
636	  border: 1px solid var(--border);
637	  border-radius: var(--radius-lg);
638	  padding: 24px;
639	  min-width: 360px;
640	  max-width: 520px;
641	  max-height: 80vh;
642	  overflow-y: auto;
643	  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
644	  animation: slideUp 0.2s ease;
645	}
646	
647	.modal-box h2 {
648	  font-size: 18px;
649	  margin-bottom: 12px;
650	  color: var(--text-primary);
651	}
652	
653	.modal-box p {
654	  font-size: 13px;
655	  color: var(--text-secondary);
656	  margin-bottom: 16px;
657	  line-height: 1.6;
658	}
659	
660	.modal-actions {
661	  display: flex;
662	  gap: 8px;
663	  justify-content: flex-end;
664	}
665	
666	/* ====== Game Over / Victory Screen ====== */
667	.end-screen {
668	  text-align: center;
669	}
670	
671	.end-screen .end-icon {
672	  font-size: 64px;
673	  margin-bottom: 16px;
674	}
675	
676	.end-screen .end-title {
677	  font-size: 28px;
678	  font-weight: 700;
679	  margin-bottom: 8px;
680	}
681	
682	.end-screen .end-subtitle {
683	  font-size: 14px;
684	  color: var(--text-secondary);
685	  margin-bottom: 20px;
686	}
687	
688	.end-screen.victory .end-title {
689	  color: var(--success);
690	}
691	.end-screen.defeat .end-title {
692	  color: var(--danger);
693	}
694	
695	/* --- Stats Summary Table --- */
696	.stats-summary {
697	  width: 100%;
698	  border-collapse: collapse;
699	  margin: 16px 0;
700	}
701	
702	.stats-summary td {
703	  padding: 6px 12px;
704	  font-size: 13px;
705	  border-bottom: 1px solid var(--border);
706	}
707	
708	.stats-summary td:first-child {
709	  color: var(--text-muted);
710	}
711	
712	.stats-summary td:last-child {
713	  text-align: right;
714	  font-weight: 600;
715	}
716	
717	/* ====== News Banner ====== */
718	.news-banner {
719	  background: linear-gradient(135deg, var(--bg-card), rgba(0, 180, 216, 0.08));
720	  border: 1px solid var(--accent);
721	  border-left: 3px solid var(--accent);
722	  border-radius: var(--radius-sm);
723	  padding: 10px 14px;
724	  font-size: 12px;
725	  color: var(--accent);
726	  flex-shrink: 0;
727	}
728	
729	.news-banner .news-icon {
730	  margin-right: 6px;
731	}
732	
733	/* ====== Event Modal (Random Story Event) ====== */
734	.event-box {
735	  min-width: 380px;
736	  max-width: 540px;
737	  border-top: 4px solid var(--accent);
738	  background: linear-gradient(180deg, var(--bg-secondary), var(--bg-card));
739	}
740	
741	.event-header {
742	  display: flex;
743	  align-items: center;
744	  gap: 12px;
745	  margin-bottom: 14px;
746	  padding-bottom: 12px;
747	  border-bottom: 1px solid var(--border);
748	}
749	
750	.event-icon {
751	  font-size: 40px;
752	  width: 56px;
753	  height: 56px;
754	  display: flex;
755	  align-items: center;
756	  justify-content: center;
757	  background: radial-gradient(circle, rgba(0, 180, 216, 0.15), transparent);
758	  border-radius: 50%;
759	  flex-shrink: 0;
760	}
761	
762	.event-title {
763	  font-size: 18px;
764	  color: var(--accent);
765	  margin: 0;
766	}
767	
768	.event-story {
769	  font-size: 13px;
770	  color: var(--text-primary);
771	  line-height: 1.7;
772	  margin-bottom: 16px;
773	  padding: 12px 14px;
774	  background: var(--bg-card);
775	  border-left: 3px solid var(--accent);
776	  border-radius: var(--radius-sm);
777	}
778	
779	.event-choices {
780	  display: flex;
781	  flex-direction: column;
782	  gap: 8px;
783	}
784	
785	.event-choice {
786	  display: block;
787	  width: 100%;
788	  text-align: left;
789	  background: var(--bg-card);
790	  border: 1px solid var(--border);
791	  border-radius: var(--radius-md);
792	  padding: 10px 14px;
793	  color: var(--text-primary);
794	  font-size: 13px;
795	  cursor: pointer;
796	  transition: all 0.15s ease;
797	  position: relative;
798	}
799	
800	.event-choice:hover:not(.disabled) {
801	  background: var(--bg-card-hover, rgba(0, 180, 216, 0.08));
802	  border-color: var(--accent);
803	  transform: translateX(2px);
804	}
805	
806	.event-choice.disabled {
807	  opacity: 0.4;
808	  cursor: not-allowed;
809	}
810	
811	.event-choice .choice-main {
812	  font-weight: 600;
813	  color: var(--text-primary);
814	}
815	
816	.event-choice .choice-hint {
817	  font-size: 11px;
818	  color: var(--text-muted);
819	  margin-top: 3px;
820	}
821	
822	/* 弹窗进入动画 */
823	@keyframes eventPop {
824	  0% {
825	    transform: scale(0.85) translateY(-20px);
826	    opacity: 0;
827	  }
828	  100% {
829	    transform: scale(1) translateY(0);
830	    opacity: 1;
831	  }
832	}
833	
834	.event-overlay,
835	.modal-overlay.event-modal {
836	  animation: fadeIn 0.2s ease;
837	}
838	
839	.event-overlay .modal-box,
840	.modal-overlay.event-modal .modal-box {
841	  animation: eventPop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
842	}
843	
844	/* ====== Utility Classes ====== */
845	.text-success {
846	  color: var(--success);
847	}
848	.text-danger {
849	  color: var(--danger);
850	}
851	.text-warning {
852	  color: var(--warning);
853	}
854	.text-accent {
855	  color: var(--accent);
856	}
857	.text-muted {
858	  color: var(--text-muted);
859	}
860	.text-sm {
861	  font-size: 11px;
862	}
863	.text-lg {
864	  font-size: 16px;
865	}
866	.font-mono {
867	  font-family: var(--font-mono);
868	}
869	
870	.flex {
871	  display: flex;
872	}
873	.flex-col {
874	  flex-direction: column;
875	}
876	.items-center {
877	  align-items: center;
878	}
879	.justify-between {
880	  justify-content: space-between;
881	}
882	.gap-2 {
883	  gap: 8px;
884	}
885	.gap-4 {
886	  gap: 16px;
887	}
888	.mt-2 {
889	  margin-top: 8px;
890	}
891	.mt-4 {
892	  margin-top: 16px;
893	}
894	.mb-2 {
895	  margin-bottom: 8px;
896	}
897	
898	/* ====== Animations ====== */
899	@keyframes fadeIn {
900	  from {
901	    opacity: 0;
902	  }
903	  to {
904	    opacity: 1;
905	  }
906	}
907	
908	@keyframes slideUp {
909	  from {
910	    opacity: 0;
911	    transform: translateY(16px);
912	  }
913	  to {
914	    opacity: 1;
915	    transform: translateY(0);
916	  }
917	}
918	
919	@keyframes pulse {
920	  0%,
921	  100% {
922	    opacity: 1;
923	  }
924	  50% {
925	    opacity: 0.5;
926	  }
927	}
928	
929	.pulse {
930	  animation: pulse 2s infinite;
931	}
932	
933	/* ====== Welcome Screen ====== */
934	.welcome-screen {
935	  display: flex;
936	  flex-direction: column;
937	  align-items: center;
938	  justify-content: center;
939	  height: 100vh;
940	  gap: 24px;
941	  text-align: center;
942	}
943	
944	.welcome-title {
945	  font-size: 36px;
946	  font-weight: 700;
947	  color: var(--accent);
948	  letter-spacing: 1px;
949	}
950	
951	.welcome-subtitle {
952	  font-size: 14px;
953	  color: var(--text-muted);
954	  max-width: 400px;
955	  line-height: 1.6;
956	}
957	
958	.welcome-buttons {
959	  display: flex;
960	  gap: 12px;
961	}
962	
963	/* ====== Tab Content Panels ====== */
964	.tab-panel {
965	  display: none;
966	}
967	
968	.tab-panel.active {
969	  display: block;
970	}
971	
972	/* ====== City Map ====== */
973	.city-map {
974	  position: relative;
975	}
976	
977	.city-map .map-node {
978	  animation: mapFadeIn 0.4s ease backwards;
979	}
980	
981	.city-map .map-node:nth-child(1) {
982	  animation-delay: 0.02s;
983	}
984	.city-map .map-node:nth-child(2) {
985	  animation-delay: 0.04s;
986	}
987	.city-map .map-node:nth-child(3) {
988	  animation-delay: 0.06s;
989	}
990	.city-map .map-node:nth-child(4) {
991	  animation-delay: 0.08s;
992	}
993	.city-map .map-node:nth-child(5) {
994	  animation-delay: 0.1s;
995	}
996	.city-map .map-node:nth-child(6) {
997	  animation-delay: 0.12s;
998	}
999	.city-map .map-node:nth-child(7) {
1000	  animation-delay: 0.14s;
1001	}
1002	.city-map .map-node:nth-child(8) {
1003	  animation-delay: 0.16s;
1004	}
1005	.city-map .map-node:nth-child(9) {
1006	  animation-delay: 0.18s;
1007	}
1008	.city-map .map-node:nth-child(10) {
1009	  animation-delay: 0.2s;
1010	}
1011	.city-map .map-node:nth-child(11) {
1012	  animation-delay: 0.22s;
1013	}
1014	
1015	@keyframes mapFadeIn {
1016	  from {
1017	    opacity: 0;
1018	    transform: translate(-50%, -50%) scale(0.8);
1019	  }
1020	  to {
1021	    opacity: 1;
1022	    transform: translate(-50%, -50%) scale(1);
1023	  }
1024	}
1025	
1026	/* Nearby locations sidebar widget */
1027	.nearby-loc-item {
1028	  cursor: pointer;
1029	  transition: all 0.2s ease;
1030	}
1031	
1032	.nearby-loc-item:hover {
1033	  border-color: var(--accent) !important;
1034	  background: var(--bg-card-hover) !important;
1035	  transform: translateX(2px);
1036	}
1037	
1038	/* Location services badges area */
1039	#location-services {
1040	  min-height: 20px;
1041	}
1042	
1043	/* ====== Responsive: Mobile ====== */
1044	@media (max-width: 768px) {
1045	  #app {
1046	    grid-template-columns: 1fr;
1047	    grid-template-areas:
1048	      "header"
1049	      "main";
1050	  }
1051	
1052	  #sidebar {
1053	    position: fixed;
1054	    left: -100%;
1055	    top: var(--header-height);
1056	    bottom: 0;
1057	    width: 280px;
1058	    z-index: 200;
1059	    transition: left 0.3s ease;
1060	    box-shadow: 2px 0 8px rgba(0, 0, 0, 0.3);
1061	  }
1062	
1063	  #sidebar.open {
1064	    left: 0;
1065	  }
1066	
1067	  .action-cards {
1068	    grid-template-columns: 1fr;
1069	  }
1070	
1071	  .header-stats {
1072	    gap: 10px;
1073	  }
1074	
1075	  .header-stat .label {
1076	    display: none;
1077	  }
1078	
1079	  #mobile-menu-btn {
1080	    display: flex !important;
1081	  }
1082	}
1083	
1084	#mobile-menu-btn {
1085	  display: none;
1086	  background: none;
1087	  border: none;
1088	  color: var(--text-primary);
1089	  font-size: 20px;
1090	  cursor: pointer;
1091	  padding: 4px;
1092	}
1093	
1094	@media (min-width: 769px) {
1095	  #mobile-menu-btn {
1096	    display: none !important;
1097	  }
1098	}
1099

