// ====== 全局错误捕获（调试用） ======
function debugLog(msg, type) {
  type = type || "info";
  console.log("[CityLife]", msg);
  const panel = document.getElementById("debug-panel");
  const content = document.getElementById("debug-content");
  if (panel && content) {
    panel.style.display = "block";
    const colors = { error: "#f44", warn: "#fa0", info: "#4af" };
    content.innerHTML += `<div style="color:${colors[type] || "#fff"};border-bottom:1px solid #333;padding:2px 0;">${msg}</div>`;
  }
}

window.addEventListener("error", (e) => {
  const msg = `ERR: ${e.message} @ ${e.filename}:${e.lineno}`;
  console.error("[CityLife]", msg);
  debugLog(msg, "error");
  const log = document.getElementById("message-log");
  if (log) {
    const c = log.querySelector(".log-content");
    if (c) {
      c.innerHTML += `<div class="log-entry danger"><span class="log-day">[ERR]</span>${e.message} (${e.filename}:${e.lineno})</div>`;
    }
  }
});

