function renderActionsTab(state, parent) {
  console.log("[CityLife] renderActionsTab called");
  let actions;
  try {
    actions = getAvailableActions(state);
    console.log(
      "[CityLife] getAvailableActions returned",
      actions.length,
      "actions:",
      actions.map((a) => a.id).join(", "),
    );
  } catch (e) {
    console.error(
      "[CityLife] getAvailableActions error:",
      e.message,
      e.stack,
    );
    parent.innerHTML =
      '<p style="color:var(--danger);">⚠️ 生成行动列表出错: ' +
      e.message +
      "</p>";
    return;
  }

  // 分离出行和其他行动
  const travelActions = actions.filter((a) => a.id.startsWith("travel_"));
  const housingActions = actions.filter(
    (a) => a.id.startsWith("housing_") || a.id.startsWith("storage_"),
  );
  const otherActions = actions.filter(
    (a) =>
      !a.id.startsWith("travel_") &&
      !a.id.startsWith("housing_") &&
      !a.id.startsWith("storage_"),
  );
  console.log(
    "[CityLife] travelActions:",
    travelActions.length,
    "housingActions:",
    housingActions.length,
    "otherActions:",
    otherActions.length,
  );

