cd "D:/Claude Code+DeepSeekV4/city-life-story" && node -e "
const fs = require('fs');
const { JSDOM } = require('jsdom');
const html = fs.readFileSync('dist/index.html', 'utf-8');
const dom = new JSDOM(html, { url: 'http://localhost/', runScripts: 'dangerously', pretendToBeVisual: true });

setTimeout(() => {
  const w = dom.window;
  w.StateManager.newGame();
  const state = w.StateManager.getState();

  // Init prices
  for (const locKey of Object.keys(w.LOCATIONS || {})) {
    state.trade.goodsPrices[locKey] = {};
    const loc = w.LOCATIONS[locKey];
    for (const good of w.GOODS || []) {
      let price = good.basePrice;
      if (loc.priceMod && loc.priceMod[good.id]) price *= loc.priceMod[good.id];
      price *= 0.9 + Math.random() * 0.2;
      price = Math.round(price * 100) / 100;
      state.trade.goodsPrices[locKey][good.id] = price;
    }
  }
  state.trade.lastPriceUpdate = state.player.day;

  // Show app and render
  w.document.getElementById('welcome-screen').style.display = 'none';
  w.document.getElementById('app').style.display = '';
  w.gameStarted = true;
  w.renderAll();

  const contentArea = w.document.getElementById('content-area');
  const actionCards = contentArea ? contentArea.querySelectorAll('.action-card') : [];
  const headings = contentArea ? contentArea.querySelectorAll('h3') : [];

  console.log('Action cards:', actionCards.length);
  console.log('Content-area children:', contentArea ? contentArea.children.length : 0);
  console.log('Sections:', [...headings].map(h => h.textContent).join(' | '));

  if (actionCards.length > 0) {
    console.log('✅ Actions tab renders correctly with', actionCards.length, 'action cards!');
  } else {
    console.log('❌ Actions tab is EMPTY!');
  }

  process.exit(0);
}, 1000);
